def parse_fasta(text):
    sequences = []
    header, seq = None, []
    for line in text.strip().splitlines():
        line = line.strip()
        if line.startswith(">"):
            if header:
                sequences.append([header, "".join(seq)])
            header, seq = line[1:], []
        else:
            seq.append(line)
    if header:
        sequences.append([header, "".join(seq)])
    return sequences

labels = ["a", "as", "b", "bs"]
chain_as, chain_bs = [], []

for i, (_, seq) in enumerate(parse_fasta(fasta)):
    system = (i // 4) + 1
    label = labels[i % 4]
    name = f"{system}{label}"
    if "s" in label:
        chain_bs.append([name, seq])
    else:
        chain_as.append([name, seq])

print("chain_as:", chain_as)
print("chain_bs:", chain_bs)